"use strict";(self.webpackChunkdocs=self.webpackChunkdocs||[]).push([[6628],{95659:e=>{e.exports=JSON.parse('{"functions":[{"name":"Register","desc":"Register a join-time snapshot sender. `name` appears in warnings only and\\nmust be unique per system; a repeat registration under the same name is\\nskipped (with a warning) instead of double-sending to every player.\\nSafe to call before or after `Initialize()`, and before or after players\\nbecome ready \u2014 an already-ready player is served immediately.","params":[{"name":"name","desc":"","lua_type":"string"},{"name":"sender","desc":"","lua_type":"(player: Player) -> ()"}],"returns":[],"function_type":"static","source":{"line":70,"path":"src/ServerStorage/SharedModules/JoinSync.luau"}},{"name":"IsReady","desc":"True once the player has announced readiness and been served.","params":[{"name":"player","desc":"","lua_type":"Player"}],"returns":[{"desc":"","lua_type":"boolean\\n"}],"function_type":"static","source":{"line":91,"path":"src/ServerStorage/SharedModules/JoinSync.luau"}},{"name":"Initialize","desc":"Connect the `ClientReady` handler. Call exactly once per server, as early as\\npossible, so no client can announce readiness before the handler exists.","params":[],"returns":[],"function_type":"static","source":{"line":100,"path":"src/ServerStorage/SharedModules/JoinSync.luau"}}],"properties":[],"types":[],"name":"JoinSync","desc":"Registry of join-time snapshot senders.\\n\\nA `Players.PlayerAdded` push is not a reliable way to deliver a snapshot: the\\nvendored `Packet` library connects the underlying `RemoteEvent` at require\\ntime and dispatches into a `Signal` with no backlog, so anything that arrives\\nbefore the consuming script has connected its own handler is silently\\ndropped. `PlayerAdded` also may not fire for the first player in a server,\\nwho can already be in `Players` when the server script runs.\\n\\nJoinSync inverts the direction: the client announces readiness with\\n`Packets.ClientReady` once its consumers are connected, and JoinSync then\\nruns every registered sender for that player. Each sender runs in its own\\nthread so one failure cannot starve the rest, and each player is served at\\nmost once.\\n\\nSystems register instead of connecting `PlayerAdded` themselves:\\n\\n```lua\\nJoinSync.Register(\\"TrainFuel\\", function(player: Player)\\n    Packets.TrainStateSync:FireClient(player, fuelAtLastEvent, currentRate, isBraked, isStalled, lastEventTime)\\nend)\\n```\\n\\nRegistration order does not matter, and registering after a player is\\nalready ready immediately serves that player \u2014 so a system whose\\n`Initialize()` runs late still reaches everyone. Names must be unique per\\nsystem; registering the same name twice is treated as a double-init bug\\nand the second registration is skipped.","realm":["Server"],"source":{"line":37,"path":"src/ServerStorage/SharedModules/JoinSync.luau"}}')}}]);